// Reads the command line into options.
export function parseArgs(argv) {
  const options = { name: 'world' };
  for (const arg of argv) {
    if (arg.startsWith('--name=')) options.name = arg.slice('--name='.length);
  }
  return options;
}

files.src/greet.js:
// Builds the greeting.
export function greet(options) {
  return `Hello, ${options.name}!`;
}

